class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  List<NewsModel>? _newsList;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadCacheAndNetwork();
  }

  void _loadCacheAndNetwork() {
    final newsRepository = context.read<NewsRepository>();

    // Показываем кэш сразу
    final cacheFuture = newsRepository.loadNewsFeed(const NewsFeedFilter.all);
    cacheFuture.then((data) {
      setState(() => _newsList = data);
      _scaleController.forward();
    });

    // Параллельно — сеть в фоне
    newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((data) {
      setState(() => _newsList = data);
      _scaleController.forward();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: _newsList == null
          ? const SizedBox.shrink()
          : ScaleTransition(
              scale: _scaleAnimation,
              child: ListView.builder(
                itemCount: _newsList!.length,
                itemBuilder: (context, index) {
                  final news = _newsList![index];
                  return Padding(
                    key: ValueKey(news.link),
                    padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                    child: NewsCard(model: news),
                  );
                },
                padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
              ),
            ),
    );
  }
}
```

Этот подход:
1. Показывает кэш мгновенно (нет задержки на сеть)
2. Параллельно загружает данные из сети
3. Обновляет список когда сеть вернётся
4. Сохраняет анимацию появления

Теперь проверю тесты — mock возвращает один и тот же список для любого аргумента, так что оба вызова (кэш и forceRefresh) вернут одинаковые данные. Тест должен продолжить работать корректно, `pumpAndSettle` подождёт оба future.

